 t.h.write(O/'previous_90_audit.csv',audit)
 loc=[dict(partition=p,method=m,origin=o,**stats([x for x in rr if x['method']==m and (o=='FAULT' and x['injected'] or x['origin']==o)])) for p,rr in parts.items() for m in ['A0','A1','A2'] for o in ['FAULT',*t.d.r.be.ORIGINS,'NORMAL']];t.h.write(O/'localization.csv',loc)
 report=dict(summary=s,gates=gates,promoted=promote,losses=losses,integrity_incremental_benign=inc,paired=[x for x in pairs if x['partition']=='VALIDATION'],previous90={k:sum(x[k] for x in audit) for k in ['integrity_observable','A0','A1','A2','unsampled','svm_default','svm_only','both_missed']},strong_success=s['A2']['detected']>s['SVM-INT default']['detected'])
 t.dump(O/'report.json',report)
 compact_keys=['run_id','method','detected','false_alarm','plant_manifestation','effective_memory_corruption','first_post_alarm_ms','latency_ms','origin_at_alarm','alarm_samples','wrong_localized_runtime_samples','alarm_UNKNOWN','localized_correct','localized_wrong','unknown_at_alarm','first_localization_ms','first_origin','propagation_plant_ms','silent_plant','integrity_observed','integrity_samples',*['alarm_'+o for o in t.d.r.be.ORIGINS]]
 compact=[{k:x[k] for k in compact_keys if k in x} for rr in parts.values() for x in rr]
 t.dump(O/'study_record.json',dict(validation_lock=json.loads((B/'lock.json').read_text()),case_metrics=dict(encoding='zlib+base85 JSON',data=base64.b85encode(zlib.compress(json.dumps(compact,separators=(',',':')).encode())).decode()),svm_model=dict(encoding='trusted local pickle+zlib+base85',data=base64.b85encode(zlib.compress((B/'svm.pkl').read_bytes())).decode()),note='Primary physical/pre-protection faults and consistent data+witness corruption not modeled by original sensor space; unit failure tests only. Historical90 separate seen cohort, not promotion.'))
 lines=['# Digital integrity development findings','',f'Promotion gates: {gates}; retained development candidate: {"A2" if promote else "A0"}. Strong raw SVM success: {report["strong_success"]}.', '', '| Method | Fault detections | Benign | Plant | Precision | Median/P95 ms |','|---|---|---|---|---|---|']
 for m,x in s.items():lines.append(f"| {m} | {x['detected']}/{x['faulty_runs']} | {x['benign_false_alarms']}/{x['benign_runs']} | {x['plant_detected']}/{x['plant_manifestation_runs']} | {x['precision']} | {x['latency_median_ms']}/{x['latency_p95_ms']} |")
 lines+=['',f'Prior90: {report["previous90"]}. Original detections lost: {len(losses)}. Incremental integrity benign runs: {inc}.','The witness is a simulated isolated acquisition driver mailbox. In ordinary unisolated C memory it has no guaranteed independent fault containment. No plant temperature, sensor model internals, labels or fault timing enters its checks. Channel values and producer timestamps are the protected payload. Legitimate reference calibration and primary sensor variation update the protected value through explicit authorized transformations, never by resealing consumer data.','Value-only corruption, replay, valid recomputed data tag, and witness-tag upset have executable boundary tests. Consistent data+witness corruption and pre-protection error intentionally pass: no coverage claim. Simultaneous ABC value mutation in the original campaign does not mutate the isolated witness; this is digital integrity coverage, not physical common-mode sensor coverage. Unsampled pulses have no sample to authenticate.','SVM has the same integrity flags/status, cross-layer/M2 evidence, sensor values and context. Default and CAL-selected empirical1% operating points are separate; report actual VALID false alarms. Binary SVM does not localize. No validation tuning or unseen execution. Only TRAIN/CAL selected comparator; integrity mapping fixed before outcomes.','Original detector thresholds, DS algebra, Triplex sensing, controller/plant and injection semantics unchanged. Development-only adapter; no production default silently enabled.']
 (O/'findings.md').write_text('\n'.join(lines)+'\n');print(json.dumps(report,indent=2),flush=True)
